import type { FilterDataStructure, FilterValue, Option } from 'models/Filters';

export function isGlobalCountryKey(country: FilterValue | undefined): boolean {
  return (
    country == null || country === '' || String(country).toUpperCase() === 'ABI'
  );
}

function withRegionBaselineOption(
  filterData: FilterDataStructure,
  options: Option[],
): Option[] {
  const baseline = filterData.region?.default;
  if (baseline?.value == null || baseline.value === '') {
    return options;
  }
  if (options.some((o) => String(o.value) === String(baseline.value))) {
    return options;
  }
  return [
    {
      value: baseline.value,
      label: baseline.label ?? 'Select a Region',
    },
    ...options,
  ];
}

/**
 * Region options from preset `dataFilters.region.values`:
 * either a flat array or a map keyed by country (ABI list for global country).
 * Prepends the preset baseline (`All`) when the country list omits it.
 */
export function getRegionOptionsForCountry(
  filterData: FilterDataStructure,
  country: FilterValue | undefined,
): Option[] {
  const raw = filterData.region?.values;
  if (!raw) return [];

  let options: Option[];
  if (Array.isArray(raw)) {
    options = raw;
  } else if (isGlobalCountryKey(country)) {
    options = raw.ABI ?? [];
  } else {
    options = raw[String(country)] ?? [];
  }

  return withRegionBaselineOption(filterData, options);
}
